/// 同处一地、可见可备份：`<kb_root>/conversations/<id>/`。
/// KB root 不可用时回退到 `~/Polaris/data/artifacts/<id>`。
pub(crate) fn conversation_dir(conv_id: Option<&str>) -> PathBuf {
